/**
 * LcdChip. A dark screen well sunk into the chassis,
 * with an emissive accent readout. Composes var(--echo-*) — no hex literals;
 * the only fixed values are the single-key-light occlusion model.
 */
.echo-lcd-chip {
  /* A readout folds rather than clipping — a truncated number lies. */
  overflow-wrap: anywhere;
  min-width: 0;
  /*
   * An inline-layout root grows to fit its content, so a long label
   * pushed the container open rather than the component adapting. Capping it
   * at the container is what lets the truncation and wrapping below take
   * effect at all.
   */
  max-width: 100%;
  /* The cap counts the padding too (BUG-128). */
  box-sizing: border-box;
  display: inline-flex;
  align-items: baseline;
  gap: var(--echo-space-4);
  padding: var(--echo-space-3) var(--echo-space-6);
  border-radius: var(--echo-radius-md);
  background: linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%);
  box-shadow:
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.85 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)));
}

.echo-lcd-chip__value {
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-xl);
  font-variant-numeric: tabular-nums;
  line-height: var(--echo-leading-none, 1);
  color: var(--echo-text);
}

/* Emissive digits: StatTile's lit accent, so the two readouts read as one
   screen. Was the pale top of the ramp — a third shade nothing else used. */
.echo-lcd-chip[data-glow] .echo-lcd-chip__value {
  color: var(--echo-accent-ink, var(--echo-accent-glow));
  text-shadow: 0 0 10px color-mix(in oklab, var(--echo-lcd-glow) 50%, transparent);
}

.echo-lcd-chip__label {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

/* roll: the digits in between are drawn (aria-hidden); the value is said
   once, by this. Tabular, so a rolling digit never changes the width. */
.echo-lcd-chip__value[data-roll] {
  white-space: pre;
}
.echo-lcd-chip__said {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Power on (useBootOnView): "off" only on a chip that starts out of view. */
.echo-lcd-chip[data-boot="off"] .echo-lcd-chip__value {
  opacity: 0;
}
.echo-lcd-chip[data-boot="on"] .echo-lcd-chip__value {
  animation: echo-lcd-boot var(--echo-duration-flood) steps(1, end) both;
}
@keyframes echo-lcd-boot {
  0% { opacity: 0; }
  18% { opacity: 0.8; }
  30% { opacity: 0.1; }
  46% { opacity: 1; }
  58% { opacity: 0.35; }
  74%, 100% { opacity: 1; }
}
/* A new value ticks over: a short flicker in steps, not a fade. */
.echo-lcd-chip__value[data-tick] {
  animation: echo-lcd-tick var(--echo-duration-sweep) steps(1, end) both;
}
@keyframes echo-lcd-tick {
  0% { opacity: 0.25; }
  30% { opacity: 1; }
  55% { opacity: 0.55; }
  75%, 100% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .echo-lcd-chip[data-boot] .echo-lcd-chip__value,
  .echo-lcd-chip__value[data-tick] {
    opacity: 1;
    animation: none;
  }
}

"use client";

/**
 * LcdChip — a recessed dark LCD readout with a glowing value and a machine
 * label. Where StatTile is a stacked tile for a
 * dashboard, LcdChip is the inline chip: value and label on one line.
 *
 * It powers on the first time it scrolls into view, flickering up in steps
 * like StatTile's screen; one already on screen at load is simply on.
 *
 * With `roll`, a new value rolls to its digits (useRoll) instead of
 * flickering over: each digit steps through the ones in between.
 */
import { useRef, type HTMLAttributes, type ReactNode } from "react";
import { useBootOnView } from "echo-ui-core/tactile";
import { useRoll } from "../roll";
import "./lcd-chip.css";

export interface LcdChipProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** The readout itself — digits, a duration, a count. */
  value: ReactNode;
  /** Machine label rendered beside the value; also the accessible name. */
  label: string;
  /** Emissive accent value. `false` renders it as plain cream text. Default true. */
  glow?: boolean;
  /**
   * A new value rolls to its digits, each stepping through the ones in
   * between, instead of flickering over. For a string or number value.
   */
  roll?: boolean;
}

export function LcdChip({ value, label, glow = true, roll = false, className, ...rest }: LcdChipProps) {
  const boot = useBootOnView<HTMLSpanElement>();
  const rolling = roll && (typeof value === "string" || typeof value === "number");
  const shown = useRoll(rolling ? String(value) : "", { enabled: rolling });
  // A new value ticks over, the way a segment display updates: the value
  // remounts (keyed by it) and flickers in steps. Not on the first render, so
  // a page never blinks as it loads.
  const first = useRef(value);
  const changed = value !== first.current;
  // A span, so the chip is phrasing content: it can sit in a button, a
  // label or a line of text, not only in a block.
  return (
    <span
      ref={boot}
      className={["echo-lcd-chip", className].filter(Boolean).join(" ")}
      data-glow={glow ? "" : undefined}
      role="group"
      aria-label={label}
      {...rest}
    >
      {rolling ? (
        // The digits in between are drawn, not read: the value is said once.
        <span className="echo-lcd-chip__value" data-roll="">
          <span aria-hidden="true">{shown}</span>
          <span className="echo-lcd-chip__said">{value}</span>
        </span>
      ) : (
        <span key={String(value)} className="echo-lcd-chip__value" data-tick={changed || undefined}>
          {value}
        </span>
      )}
      <span className="echo-lcd-chip__label">{label}</span>
    </span>
  );
}
